-- Commercial source views: the loans of wip.VwCommercialSubmissionCR joined to the uploaded workbook's sheets
-- (automn.stg_commercial_*). Run 00_functions.sql and 01_reference.sql first. Run in rarfinmisdb in SSMS / Azure Data
-- Studio (GO separates batches); safe to run again (CREATE OR ALTER). A change here needs no app redeployment.
-- Portable source (2026-11-02): tools/build_views.py generates the Postgres / MySQL copies from this file, so write only
-- what it translates correctly: CONCAT (never '...' + ...), automn.fn_amount / fn_percent / fn_int (never TRY_CAST),
-- joins to automn.vw_ref_label / vw_ref_code for labels and codes (never a function), and CAST source-view values to
-- VARCHAR before text functions. The build refuses the forbidden forms.
--
-- What the app expects (submissions/adapters/views.py): one view per canonical entity, automn.vw_commercial_<entity>,
-- returning the entity's columns by name with canonical values, plus load_id (the upload), which the app filters on.
-- vw_commercial_account also returns as_of_date (the source view's transactiondate), filtered on the request's date.
-- A column a view does not return is NULL.
-- Check after a change (read-only):  python -m submissions.adapters.views COMMERCIAL --as-of 2026-10-28 --load-id <n>
--
-- Rules (user decisions, 2026-10-29 / 30, append-only staging 2026-11-02):
--   - Every join is on the Sanction Reference Number: view SanctionRefNo = Sanction = BS / AS / RS / GS / SS / CD,
--     compared on letters and digits only (automn.fn_ref_key: F012/2025-26 = F012-2025-26).
--   - Staging is append only: every upload adds its rows. A reference's workbook data (all sheets) is its rows in the
--     NEWEST successfully loaded upload (input_load.status = 'LOADED') whose Sanction sheet has it, whichever request
--     that upload belongs to. A sheet with no rows for the reference in that upload gives none (no mixing of uploads).
--   - A request reports the references in its own upload's Sanction sheet (load_id), with that newest data.
--   - The loan (CR) line stays at transaction-date level: vw_commercial_account is the only view with as_of_date.
--     The other views have no date: a reference is resolved to its loan accounts once (vw_commercial_ref_account).
--   - Where a reference has several Sanction rows (several loans), its FIRST row (Excel order) gives credit type,
--     repayment frequency and suit details for each of its loans (the upload check SANCTION_ROWS_DIFFER warns).
--   - One borrower per loan account: party_key = the view's AccountNumber, filled from the reference's BS row.
--   - The view wins where it has the field (the CR line). Credit type, repayment frequency and suit details are not
--     in the view: they come from Sanction.
--   - CD rows with nothing filled are not reported. Fax Number(s) is not reported (it held e-mails).
--   - '(Name)' columns hold labels -> join automn.vw_ref_label; code columns -> join automn.vw_ref_code
--     (01_reference.sql): an unknown value is passed on as it is, so validation reports it.
CREATE OR REPLACE VIEW automn.vw_commercial_upload_ref AS
SELECT
  u.load_id,
  u.ref_key,
  n.source_load_id,
  l.loaded_at AS source_loaded_at
FROM (
  SELECT DISTINCT
    load_id,
    automn.fn_ref_key(sanction_reference_number) AS ref_key
  FROM automn.stg_commercial_sanction
) AS u
JOIN (
  SELECT
    automn.fn_ref_key(s.sanction_reference_number) AS ref_key,
    MAX(s.load_id) AS source_load_id
  FROM automn.stg_commercial_sanction AS s
  JOIN automn.input_load AS i
    ON i.load_id = s.load_id AND i.status = 'LOADED'
  GROUP BY
    automn.fn_ref_key(s.sanction_reference_number)
) AS n
  ON n.ref_key = u.ref_key
JOIN automn.input_load AS l
  ON l.load_id = n.source_load_id;

-- Each loan account's reference, without the date: the reference on the account's latest transactiondate.
CREATE OR REPLACE VIEW automn.vw_commercial_ref_account AS
SELECT
  x.ref_key,
  x.AccountNumber
FROM (
  SELECT
    automn.fn_ref_key(v.SanctionRefNo) AS ref_key,
    v.AccountNumber,
    ROW_NUMBER() OVER (PARTITION BY v.AccountNumber ORDER BY v.transactiondate DESC NULLS LAST) AS rn
  FROM wip.VwCommercialSubmissionCR AS v
) AS x
WHERE
  x.rn = 1;

-- Each upload's first BS row per reference (Excel order): joined on (load_id = source_load_id, ref_key).
CREATE OR REPLACE VIEW automn.vw_commercial_bs_first AS
SELECT
  y.*
FROM (
  SELECT
    x.*,
    automn.fn_ref_key(x.sanction_reference_number) AS ref_key,
    ROW_NUMBER() OVER (
      PARTITION BY x.load_id, automn.fn_ref_key(x.sanction_reference_number)
      ORDER BY x.source_row NULLS FIRST
    ) AS rn
  FROM automn.stg_commercial_bs AS x
) AS y
WHERE
  y.rn = 1;

-- ---------------------------------------------------------------- the loans of each upload: view (per date) x the
-- reference's first Sanction row in its newest upload
CREATE OR REPLACE VIEW automn.vw_commercial_loan AS
SELECT
  u.load_id,
  u.source_load_id,
  u.source_loaded_at,
  v.transactiondate AS as_of_date,
  v.*,
  n.sanction_reference_number AS ref,
  u.ref_key,
  n.credit_type_label,
  n.repayment_frequency_label,
  n.suit_filed_status AS suit_code,
  n.suit_reference_number,
  n.suit_amount_in_rupees,
  n.date_of_suit_filing
FROM wip.VwCommercialSubmissionCR AS v
JOIN automn.vw_commercial_upload_ref AS u
  ON u.ref_key = automn.fn_ref_key(v.SanctionRefNo)
JOIN (
  SELECT
    x.*,
    ROW_NUMBER() OVER (
      PARTITION BY x.load_id, automn.fn_ref_key(x.sanction_reference_number)
      ORDER BY x.source_row NULLS FIRST
    ) AS rn
  FROM automn.stg_commercial_sanction AS x
) AS n
  ON n.load_id = u.source_load_id
  AND automn.fn_ref_key(n.sanction_reference_number) = u.ref_key
  AND n.rn = 1;

-- Each upload reference's loan accounts (no date), for the child sheets: load_id, source_load_id, ref_key, account.
CREATE OR REPLACE VIEW automn.vw_commercial_upload_account AS
SELECT
  u.load_id,
  u.source_load_id,
  u.ref_key,
  ra.AccountNumber
FROM automn.vw_commercial_upload_ref AS u
JOIN automn.vw_commercial_ref_account AS ra
  ON ra.ref_key = u.ref_key;

-- Each upload's loan accounts and their Sanction Reference Number (as written in the reference's first Sanction row
-- of its newest upload), no date: the customer tables keep one borrower per sanction and link its accounts
-- (owner 2026-11-11; read by sources.master_load, not a snapshot entity).
CREATE OR REPLACE VIEW automn.vw_commercial_account_ref AS
SELECT DISTINCT
  u.load_id,
  CAST(u.AccountNumber AS VARCHAR(50)) AS account_number,
  CAST(n.sanction_reference_number AS VARCHAR(100)) AS sanction_reference_number
FROM automn.vw_commercial_upload_account AS u
JOIN (
  SELECT
    x.load_id,
    x.sanction_reference_number,
    automn.fn_ref_key(x.sanction_reference_number) AS ref_key,
    ROW_NUMBER() OVER (
      PARTITION BY x.load_id, automn.fn_ref_key(x.sanction_reference_number)
      ORDER BY x.source_row NULLS FIRST
    ) AS rn
  FROM automn.stg_commercial_sanction AS x
) AS n
  ON n.load_id = u.source_load_id AND n.ref_key = u.ref_key AND n.rn = 1;

-- ---------------------------------------------------------------- CR: the loan line
-- The inner select prepares the view's coded values: numbers padded to their code width (5 -> 05; 1012025 -> 01012025,
-- the dates the view holds as numbers), NULL kept as NULL.
CREATE OR REPLACE VIEW automn.vw_commercial_account AS
SELECT
  l.load_id,
  l.source_load_id,
  l.source_loaded_at,
  l.as_of_date,
  l.AccountNumber AS account_key,
  l.AccountNumber AS account_number,
  b.member_branch_code AS branch_code,
  b.previous_member_branch_code AS previous_branch_code,
  l."Previous Account Number" AS previous_account_number,
  COALESCE(l_type.code, NULLIF(LTRIM(RTRIM(l.credit_type_label)), '')) AS account_type,
  automn.fn_date(CAST(l."Sanction Date" AS VARCHAR(40))) AS date_opened,
  l."Sanctioned Amount" AS sanctioned_amount,
  l."Currency Code" AS currency,
  l.Tenure AS repayment_tenure,
  COALESCE(l_freq.code, NULLIF(LTRIM(RTRIM(l.repayment_frequency_label)), '')) AS payment_frequency,
  l."Drawing Power" AS drawing_power,
  l."Current Balance" AS current_balance,
  l."Notional Amount of Outstanding Restructured Contracts" AS restructured_notional_amount,
  automn.fn_date(CAST(l."Maturity Date" AS VARCHAR(40))) AS maturity_date,
  automn.fn_date(l.renewal_text) AS renewal_date,
  l.RBIODDays AS days_past_due,
  COALESCE(c_asset.code, l.asset_code) AS asset_classification,
  automn.fn_date(l.asset_class_date_text) AS asset_classification_date,
  l."Amount Overdue" AS amount_overdue,
  l."Overdue Bucket 01 ( 1 – 30 days)" AS overdue_bucket_1,
  l."Overdue Bucket 02 ( 31 – 60 days)" AS overdue_bucket_2,
  l."Overdue Bucket 03 ( 61 – 90 days)" AS overdue_bucket_3,
  l."Overdue Bucket 04 (91 – 180 days)" AS overdue_bucket_4,
  l."Overdue Bucket 05 (Above 180 days)" AS overdue_bucket_5,
  l."High Credit" AS high_credit_amount,
  l."Installment Amount" AS emi_amount,
  l."Last Repaid Amount" AS actual_payment_amount,
  l.LastPaymentDate AS date_last_payment,
  CASE
    WHEN l.status_code IN ('01', '02')
    THEN NULL
    ELSE COALESCE(c_status.code, l.status_code)
  END AS credit_facility_status,
  automn.fn_date(CAST(l."Account Status Date" AS VARCHAR(40))) AS status_date,
  CASE WHEN l.IsAccountClosed = 'Yes' THEN l.AcClosedDate END AS date_closed,
  l."Written Off Amount" AS written_off_total,
  l."Settled Amount" AS settlement_amount,
  COALESCE(c_restr.code, l.restructuring_code) AS restructuring_reason,
  l."Amount of Contracts Classified as NPA" AS npa_contracts_amount,
  COALESCE(c_seccov.code, l.security_coverage_code) AS security_coverage,
  COALESCE(c_guarcov.code, l.guarantee_coverage_code) AS guarantee_coverage,
  CAST(l."Bank Remark Code" AS VARCHAR(10)) AS remark,
  automn.fn_date(l.wilful_date_text) AS wilful_default_date,
  COALESCE(c_suit.code, l.suit_code_value) AS suit_filed_status,
  l.suit_reference_number AS suit_reference,
  automn.fn_amount(l.suit_amount_in_rupees) AS suit_amount,
  automn.fn_date(l.date_of_suit_filing) AS suit_date,
  CAST(l."Dispute ID No." AS VARCHAR(30)) AS dispute_id,
  l.OTHER_BK AS other_lenders,
  l."UFCE Amount" AS ufce_amount,
  automn.fn_date(l.ufce_date_text) AS ufce_date
FROM (
  SELECT
    y.*,
    CASE
      WHEN NOT y."Loan Renewal Date" IS NULL
      THEN RIGHT(CAST(CONCAT('0', CAST(y."Loan Renewal Date" AS VARCHAR(8))) AS TEXT), 8)
    END AS renewal_text,
    CASE
      WHEN NOT y."Asset Classification Date" IS NULL
      THEN RIGHT(CAST(CONCAT('0', CAST(y."Asset Classification Date" AS VARCHAR(8))) AS TEXT), 8)
    END AS asset_class_date_text,
    CASE
      WHEN NOT y."Date Classified as Wilful Default" IS NULL
      THEN RIGHT(
        CAST(CONCAT('0', CAST(y."Date Classified as Wilful Default" AS VARCHAR(8))) AS TEXT),
        8
      )
    END AS wilful_date_text,
    CASE
      WHEN NOT y."UFCE Date" IS NULL
      THEN RIGHT(CAST(CONCAT('0', CAST(y."UFCE Date" AS VARCHAR(8))) AS TEXT), 8)
    END AS ufce_date_text,
    NULLIF(LTRIM(RTRIM(CAST(y."Asset Classification" AS VARCHAR(40)))), '') AS asset_code,
    NULLIF(LTRIM(RTRIM(CAST(y."Account Status" AS VARCHAR(40)))), '') AS status_code,
    CASE
      WHEN NOT y."Major reasons for Restructuring" IS NULL
      THEN RIGHT(
        CAST(CONCAT('0', CAST(y."Major reasons for Restructuring" AS VARCHAR(2))) AS TEXT),
        2
      )
    END AS restructuring_code,
    CASE
      WHEN NOT y."Asset based Security coverage" IS NULL
      THEN RIGHT(
        CAST(CONCAT('0', CAST(y."Asset based Security coverage" AS VARCHAR(2))) AS TEXT),
        2
      )
    END AS security_coverage_code,
    CASE
      WHEN NOT y."Guarantee Coverage" IS NULL
      THEN RIGHT(CAST(CONCAT('0', CAST(y."Guarantee Coverage" AS VARCHAR(2))) AS TEXT), 2)
    END AS guarantee_coverage_code,
    NULLIF(LTRIM(RTRIM(y.suit_code)), '') AS suit_code_value
  FROM automn.vw_commercial_loan AS y
) AS l
LEFT JOIN automn.vw_commercial_bs_first AS b
  ON b.load_id = l.source_load_id AND b.ref_key = l.ref_key
LEFT JOIN automn.vw_ref_label AS l_type
  ON l_type.submission_type = 'COMMERCIAL'
  AND l_type.code_list = 'account_type'
  AND l_type.label_key = UPPER(LTRIM(RTRIM(l.credit_type_label)))
LEFT JOIN automn.vw_ref_label AS l_freq
  ON l_freq.submission_type = 'COMMERCIAL'
  AND l_freq.code_list = 'payment_frequency'
  AND l_freq.label_key = UPPER(LTRIM(RTRIM(l.repayment_frequency_label)))
LEFT JOIN automn.vw_ref_code AS c_asset
  ON c_asset.submission_type = 'COMMERCIAL'
  AND c_asset.code_list = 'asset_classification'
  AND c_asset.code_key = UPPER(l.asset_code)
LEFT JOIN automn.vw_ref_code AS c_status
  ON c_status.submission_type = 'COMMERCIAL'
  AND c_status.code_list = 'credit_facility_status'
  AND c_status.code_key = UPPER(l.status_code)
LEFT JOIN automn.vw_ref_code AS c_restr
  ON c_restr.submission_type = 'COMMERCIAL'
  AND c_restr.code_list = 'restructuring_reason'
  AND c_restr.code_key = l.restructuring_code
LEFT JOIN automn.vw_ref_code AS c_seccov
  ON c_seccov.submission_type = 'COMMERCIAL'
  AND c_seccov.code_list = 'coverage'
  AND c_seccov.code_key = l.security_coverage_code
LEFT JOIN automn.vw_ref_code AS c_guarcov
  ON c_guarcov.submission_type = 'COMMERCIAL'
  AND c_guarcov.code_list = 'coverage'
  AND c_guarcov.code_key = l.guarantee_coverage_code
LEFT JOIN automn.vw_ref_code AS c_suit
  ON c_suit.submission_type = 'COMMERCIAL'
  AND c_suit.code_list = 'suit_filed_status'
  AND c_suit.code_key = UPPER(l.suit_code_value);

-- ---------------------------------------------------------------- BS: one borrower per loan account (no date; the
-- date is applied once, in vw_commercial_account; borrowers link to loans through vw_commercial_account_holder)
CREATE OR REPLACE VIEW automn.vw_commercial_party AS
SELECT
  l.load_id,
  l.source_load_id,
  l.AccountNumber AS party_key,
  b.borrower_name AS full_name,
  b.borrower_short_name AS short_name,
  COALESCE(l_const.code, NULLIF(LTRIM(RTRIM(b.borrowers_legal_constitution_label)), '')) AS legal_constitution,
  COALESCE(l_cat.code, NULLIF(LTRIM(RTRIM(b.business_category_label)), '')) AS business_category,
  COALESCE(l_ind.code, NULLIF(LTRIM(RTRIM(b.business_industry_type_label)), '')) AS industry_type,
  automn.fn_date(b.date_of_incorporation) AS incorporation_date,
  b.class_of_activity_1 AS activity_class_1,
  b.class_of_activity_2 AS activity_class_2,
  b.class_of_activity_3 AS activity_class_3,
  b.sic_code AS hsn_code,
  automn.fn_amount(b.sales_figure) AS sales_amount,
  automn.fn_date(b.financial_year) AS sales_year,
  automn.fn_int(b.number_of_employees) AS employee_count,
  b.credit_rating,
  COALESCE(l_agency.code, NULLIF(LTRIM(RTRIM(b.assessment_agency_authority)), '')) AS rating_agency,
  automn.fn_date(b.credit_rating_as_on) AS rating_date,
  automn.fn_date(b.credit_rating_expiry_date) AS rating_expiry_date
FROM automn.vw_commercial_upload_account AS l
JOIN automn.vw_commercial_bs_first AS b
  ON b.load_id = l.source_load_id AND b.ref_key = l.ref_key
LEFT JOIN automn.vw_ref_label AS l_const
  ON l_const.submission_type = 'COMMERCIAL'
  AND l_const.code_list = 'legal_constitution'
  AND l_const.label_key = UPPER(LTRIM(RTRIM(b.borrowers_legal_constitution_label)))
LEFT JOIN automn.vw_ref_label AS l_cat
  ON l_cat.submission_type = 'COMMERCIAL'
  AND l_cat.code_list = 'business_category'
  AND l_cat.label_key = UPPER(LTRIM(RTRIM(b.business_category_label)))
LEFT JOIN automn.vw_ref_label AS l_ind
  ON l_ind.submission_type = 'COMMERCIAL'
  AND l_ind.code_list = 'industry_type'
  AND l_ind.label_key = UPPER(LTRIM(RTRIM(b.business_industry_type_label)))
LEFT JOIN automn.vw_ref_label AS l_agency
  ON l_agency.submission_type = 'COMMERCIAL'
  AND l_agency.code_list = 'rating_agency'
  AND l_agency.label_key = UPPER(LTRIM(RTRIM(b.assessment_agency_authority)));

CREATE OR REPLACE VIEW automn.vw_commercial_account_holder AS
SELECT
  p.load_id,
  p.party_key AS account_key,
  p.party_key
FROM automn.vw_commercial_party AS p;

CREATE OR REPLACE VIEW automn.vw_commercial_party_identifier AS
SELECT
  l.load_id,
  l.AccountNumber AS party_key,
  d.id_type,
  d.id_number
FROM automn.vw_commercial_upload_account AS l
JOIN automn.vw_commercial_bs_first AS b
  ON b.load_id = l.source_load_id AND b.ref_key = l.ref_key CROSS JOIN LATERAL (
  VALUES
    ('PAN', b.pan),
    ('CIN', b.cin),
    ('TIN', b.tin),
    ('SERVICE_TAX', b.service_tax_no),
    ('COMPANY_REGISTRATION', b.company_registration_number)
) AS d(id_type, id_number)
WHERE
  NOT NULLIF(LTRIM(RTRIM(d.id_number)), '') IS NULL;

-- ---------------------------------------------------------------- AS: the borrower's addresses and phones
CREATE OR REPLACE VIEW automn.vw_commercial_party_address AS
SELECT
  l.load_id,
  l.AccountNumber AS party_key,
  COALESCE(l_cat.code, NULLIF(LTRIM(RTRIM(a.borrower_office_location_type_label)), '')) AS address_category,
  a.address_line_1,
  a.address_line_2,
  a.address_line_3,
  a.city_town AS city,
  a.district,
  COALESCE(l_state.code, NULLIF(LTRIM(RTRIM(a.state_label)), '')) AS state_code,
  a.pin_code,
  COALESCE(l_country.code, NULLIF(LTRIM(RTRIM(a.country_label)), '')) AS country,
  a.source_row AS priority
FROM automn.vw_commercial_upload_account AS l
JOIN automn.stg_commercial_as AS a
  ON a.load_id = l.source_load_id
  AND automn.fn_ref_key(a.sanction_reference_number) = l.ref_key
LEFT JOIN automn.vw_ref_label AS l_cat
  ON l_cat.submission_type = 'COMMERCIAL'
  AND l_cat.code_list = 'address_category'
  AND l_cat.label_key = UPPER(LTRIM(RTRIM(a.borrower_office_location_type_label)))
LEFT JOIN automn.vw_ref_label AS l_state
  ON l_state.submission_type = 'COMMERCIAL'
  AND l_state.code_list = 'state_code'
  AND l_state.label_key = UPPER(LTRIM(RTRIM(a.state_label)))
LEFT JOIN automn.vw_ref_label AS l_country
  ON l_country.submission_type = 'COMMERCIAL'
  AND l_country.code_list = 'country'
  AND l_country.label_key = UPPER(LTRIM(RTRIM(a.country_label)));

CREATE OR REPLACE VIEW automn.vw_commercial_party_phone AS
SELECT
  l.load_id,
  l.AccountNumber AS party_key,
  p.phone_number,
  p.phone_type,
  p.priority
FROM automn.vw_commercial_upload_account AS l
JOIN automn.stg_commercial_as AS a
  ON a.load_id = l.source_load_id
  AND automn.fn_ref_key(a.sanction_reference_number) = l.ref_key CROSS JOIN LATERAL (
  VALUES
    (a.mobile_number_s, 'MOBILE', a.source_row),
    (
      CASE
        WHEN NOT NULLIF(LTRIM(RTRIM(a.telephone_number_s)), '') IS NULL
        THEN CONCAT_WS('-', NULLIF(LTRIM(RTRIM(a.telephone_area_code)), ''), a.telephone_number_s)
      END,
      'OFFICE',
      a.source_row + 100000
    )
) AS p(phone_number, phone_type, priority)
WHERE
  NOT NULLIF(LTRIM(RTRIM(p.phone_number)), '') IS NULL;

-- ---------------------------------------------------------------- RS: related parties of the borrower
CREATE OR REPLACE VIEW automn.vw_commercial_relationship AS
SELECT
  l.load_id,
  l.AccountNumber AS party_key,
  COALESCE(l_rel.code, NULLIF(LTRIM(RTRIM(r.relationship_label)), '')) AS relationship_type,
  automn.fn_percent(r.percentage_of_control) AS control_percentage,
  CONCAT('RS-', r.sanction_reference_number, '-', r.source_row) AS related_key,
  COALESCE(l_rtype.code, NULLIF(LTRIM(RTRIM(r.related_type_label)), '')) AS related_type,
  COALESCE(NULLIF(LTRIM(RTRIM(r.full_name)), ''), r.business_entity_name) AS full_name,
  r.individual_name_prefix AS name_prefix,
  COALESCE(l_cat.code, NULLIF(LTRIM(RTRIM(r.business_category)), '')) AS business_category,
  COALESCE(l_ind.code, NULLIF(LTRIM(RTRIM(r.business_industry_type)), '')) AS industry_type,
  COALESCE(l_gender.code, NULLIF(LTRIM(RTRIM(r.gender_label)), '')) AS gender,
  automn.fn_date(r.date_of_birth) AS birth_date,
  automn.fn_date(r.date_of_incorporation) AS incorporation_date,
  r.pan,
  r.voter_id,
  r.passport_number AS passport,
  r.driving_licence_id AS driving_licence,
  r.uid AS aadhaar,
  r.ration_card_no AS ration_card,
  r.company_registration_number AS company_registration,
  r.cin,
  r.din,
  r.tin,
  r.service_tax_no AS service_tax,
  r.address_line_1,
  r.address_line_2,
  r.address_line_3,
  r.city_town AS city,
  r.district,
  COALESCE(l_state.code, NULLIF(LTRIM(RTRIM(r.state_label)), '')) AS state_code,
  r.pin_code,
  COALESCE(l_country.code, NULLIF(LTRIM(RTRIM(r.country_label)), '')) AS country,
  r.mobile_number_s AS mobile,
  r.telephone_number_s AS telephone,
  r.telephone_area_code
FROM automn.vw_commercial_upload_account AS l
JOIN automn.stg_commercial_rs AS r
  ON r.load_id = l.source_load_id
  AND automn.fn_ref_key(r.sanction_reference_number) = l.ref_key
LEFT JOIN automn.vw_ref_label AS l_rel
  ON l_rel.submission_type = 'COMMERCIAL'
  AND l_rel.code_list = 'relationship_type'
  AND l_rel.label_key = UPPER(LTRIM(RTRIM(r.relationship_label)))
LEFT JOIN automn.vw_ref_label AS l_rtype
  ON l_rtype.submission_type = 'COMMERCIAL'
  AND l_rtype.code_list = 'related_type'
  AND l_rtype.label_key = UPPER(LTRIM(RTRIM(r.related_type_label)))
LEFT JOIN automn.vw_ref_label AS l_cat
  ON l_cat.submission_type = 'COMMERCIAL'
  AND l_cat.code_list = 'business_category'
  AND l_cat.label_key = UPPER(LTRIM(RTRIM(r.business_category)))
LEFT JOIN automn.vw_ref_label AS l_ind
  ON l_ind.submission_type = 'COMMERCIAL'
  AND l_ind.code_list = 'industry_type'
  AND l_ind.label_key = UPPER(LTRIM(RTRIM(r.business_industry_type)))
LEFT JOIN automn.vw_ref_label AS l_gender
  ON l_gender.submission_type = 'COMMERCIAL'
  AND l_gender.code_list = 'gender'
  AND l_gender.label_key = UPPER(LTRIM(RTRIM(r.gender_label)))
LEFT JOIN automn.vw_ref_label AS l_state
  ON l_state.submission_type = 'COMMERCIAL'
  AND l_state.code_list = 'state_code'
  AND l_state.label_key = UPPER(LTRIM(RTRIM(r.state_label)))
LEFT JOIN automn.vw_ref_label AS l_country
  ON l_country.submission_type = 'COMMERCIAL'
  AND l_country.code_list = 'country'
  AND l_country.label_key = UPPER(LTRIM(RTRIM(r.country_label)));

-- ---------------------------------------------------------------- GS: guarantors of the loan
CREATE OR REPLACE VIEW automn.vw_commercial_guarantor AS
SELECT
  l.load_id,
  l.AccountNumber AS account_key,
  CONCAT('GS-', g.sanction_reference_number, '-', g.source_row) AS related_key,
  COALESCE(l_rtype.code, NULLIF(LTRIM(RTRIM(g.guarantor_type_label)), '')) AS related_type,
  COALESCE(NULLIF(LTRIM(RTRIM(g.full_name)), ''), g.guarantor_entity_name) AS full_name,
  g.individual_name_prefix AS name_prefix,
  COALESCE(l_cat.code, NULLIF(LTRIM(RTRIM(g.business_category_label)), '')) AS business_category,
  COALESCE(l_ind.code, NULLIF(LTRIM(RTRIM(g.business_industry_type_label)), '')) AS industry_type,
  COALESCE(l_gender.code, NULLIF(LTRIM(RTRIM(g.gender_label)), '')) AS gender,
  automn.fn_date(g.date_of_birth) AS birth_date,
  automn.fn_date(g.date_of_incorporation) AS incorporation_date,
  g.pan,
  g.voter_id,
  g.passport_number AS passport,
  g.driving_licence_id AS driving_licence,
  g.uid AS aadhaar,
  g.ration_card_no AS ration_card,
  g.company_registration_number AS company_registration,
  g.cin,
  g.din,
  g.tin,
  g.service_tax_no AS service_tax,
  g.address_line_1,
  g.address_line_2,
  g.address_line_3,
  g.city_town AS city,
  g.district,
  COALESCE(l_state.code, NULLIF(LTRIM(RTRIM(g.state_label)), '')) AS state_code,
  g.pin_code,
  COALESCE(l_country.code, NULLIF(LTRIM(RTRIM(g.country_label)), '')) AS country,
  g.mobile_number_s AS mobile,
  g.telephone_number_s AS telephone,
  g.telephone_area_code
FROM automn.vw_commercial_upload_account AS l
JOIN automn.stg_commercial_gs AS g
  ON g.load_id = l.source_load_id
  AND automn.fn_ref_key(g.sanction_reference_number) = l.ref_key
LEFT JOIN automn.vw_ref_label AS l_rtype
  ON l_rtype.submission_type = 'COMMERCIAL'
  AND l_rtype.code_list = 'related_type'
  AND l_rtype.label_key = UPPER(LTRIM(RTRIM(g.guarantor_type_label)))
LEFT JOIN automn.vw_ref_label AS l_cat
  ON l_cat.submission_type = 'COMMERCIAL'
  AND l_cat.code_list = 'business_category'
  AND l_cat.label_key = UPPER(LTRIM(RTRIM(g.business_category_label)))
LEFT JOIN automn.vw_ref_label AS l_ind
  ON l_ind.submission_type = 'COMMERCIAL'
  AND l_ind.code_list = 'industry_type'
  AND l_ind.label_key = UPPER(LTRIM(RTRIM(g.business_industry_type_label)))
LEFT JOIN automn.vw_ref_label AS l_gender
  ON l_gender.submission_type = 'COMMERCIAL'
  AND l_gender.code_list = 'gender'
  AND l_gender.label_key = UPPER(LTRIM(RTRIM(g.gender_label)))
LEFT JOIN automn.vw_ref_label AS l_state
  ON l_state.submission_type = 'COMMERCIAL'
  AND l_state.code_list = 'state_code'
  AND l_state.label_key = UPPER(LTRIM(RTRIM(g.state_label)))
LEFT JOIN automn.vw_ref_label AS l_country
  ON l_country.submission_type = 'COMMERCIAL'
  AND l_country.code_list = 'country'
  AND l_country.label_key = UPPER(LTRIM(RTRIM(g.country_label)));

-- ---------------------------------------------------------------- SS: security of the loan
CREATE OR REPLACE VIEW automn.vw_commercial_security AS
SELECT
  l.load_id,
  l.AccountNumber AS account_key,
  automn.fn_amount(s.value_of_security) AS security_value,
  s.currency_type AS currency,
  COALESCE(l_type.code, NULLIF(LTRIM(RTRIM(s.type_of_security_label)), '')) AS security_type,
  COALESCE(l_class.code, NULLIF(LTRIM(RTRIM(s.security_classification_label)), '')) AS security_classification,
  automn.fn_date(s.date_of_valuation) AS valuation_date
FROM automn.vw_commercial_upload_account AS l
JOIN automn.stg_commercial_ss AS s
  ON s.load_id = l.source_load_id
  AND automn.fn_ref_key(s.sanction_reference_number) = l.ref_key
LEFT JOIN automn.vw_ref_label AS l_type
  ON l_type.submission_type = 'COMMERCIAL'
  AND l_type.code_list = 'security_type'
  AND l_type.label_key = UPPER(LTRIM(RTRIM(s.type_of_security_label)))
LEFT JOIN automn.vw_ref_label AS l_class
  ON l_class.submission_type = 'COMMERCIAL'
  AND l_class.code_list = 'security_classification'
  AND l_class.label_key = UPPER(LTRIM(RTRIM(s.security_classification_label)));

-- ---------------------------------------------------------------- CD: cheque dishonour, filled rows only
CREATE OR REPLACE VIEW automn.vw_commercial_cheque_dishonour AS
SELECT
  l.load_id,
  l.AccountNumber AS account_key,
  automn.fn_date(c.date_of_dishonour) AS dishonour_date,
  automn.fn_amount(c.amount) AS amount,
  c.instrument_cheque_number AS instrument_number,
  automn.fn_int(c.number_of_times_dishonoured) AS dishonour_count,
  automn.fn_date(c.cheque_issue_date) AS cheque_issue_date,
  COALESCE(l_reason.code, NULLIF(LTRIM(RTRIM(c.reason_for_dishonour)), '')) AS reason
FROM automn.vw_commercial_upload_account AS l
JOIN automn.stg_commercial_cd AS c
  ON c.load_id = l.source_load_id
  AND automn.fn_ref_key(c.sanction_reference_number) = l.ref_key
LEFT JOIN automn.vw_ref_label AS l_reason
  ON l_reason.submission_type = 'COMMERCIAL'
  AND l_reason.code_list = 'dishonour_reason'
  AND l_reason.label_key = UPPER(LTRIM(RTRIM(c.reason_for_dishonour)))
WHERE
  NOT COALESCE(
    c.date_of_dishonour,
    c.amount,
    c.instrument_cheque_number,
    c.number_of_times_dishonoured,
    c.cheque_issue_date,
    c.reason_for_dishonour
  ) IS NULL;

-- ---------------------------------------------------------------- the account's workbook fields, no date (owner
-- 2026-11-12): what the customer tables keep for each loan account of an upload: from the reference's first Sanction
-- row (credit type, repayment frequency, suit) and BS row (branches). The LMS's fields are read at request time, by
-- the request's as-of date (vw_pos_account_position). Read by sources.master_load.
CREATE OR REPLACE VIEW automn.vw_commercial_account_static AS
SELECT
  u.load_id,
  CAST(u.AccountNumber AS VARCHAR(50)) AS account_key,
  CAST(u.AccountNumber AS VARCHAR(50)) AS account_number,
  b.member_branch_code AS branch_code,
  b.previous_member_branch_code AS previous_branch_code,
  COALESCE(l_type.code, NULLIF(LTRIM(RTRIM(n.credit_type_label)), '')) AS account_type,
  COALESCE(l_freq.code, NULLIF(LTRIM(RTRIM(n.repayment_frequency_label)), '')) AS payment_frequency,
  COALESCE(c_suit.code, NULLIF(LTRIM(RTRIM(n.suit_filed_status)), '')) AS suit_filed_status,
  n.suit_reference_number AS suit_reference,
  automn.fn_amount(n.suit_amount_in_rupees) AS suit_amount,
  automn.fn_date(n.date_of_suit_filing) AS suit_date
FROM automn.vw_commercial_upload_account AS u
JOIN (
  SELECT
    x.*,
    automn.fn_ref_key(x.sanction_reference_number) AS ref_key,
    ROW_NUMBER() OVER (
      PARTITION BY x.load_id, automn.fn_ref_key(x.sanction_reference_number)
      ORDER BY x.source_row NULLS FIRST
    ) AS rn
  FROM automn.stg_commercial_sanction AS x
) AS n
  ON n.load_id = u.source_load_id AND n.ref_key = u.ref_key AND n.rn = 1
LEFT JOIN automn.vw_commercial_bs_first AS b
  ON b.load_id = u.source_load_id AND b.ref_key = u.ref_key
LEFT JOIN automn.vw_ref_label AS l_type
  ON l_type.submission_type = 'COMMERCIAL'
  AND l_type.code_list = 'account_type'
  AND l_type.label_key = UPPER(LTRIM(RTRIM(n.credit_type_label)))
LEFT JOIN automn.vw_ref_label AS l_freq
  ON l_freq.submission_type = 'COMMERCIAL'
  AND l_freq.code_list = 'payment_frequency'
  AND l_freq.label_key = UPPER(LTRIM(RTRIM(n.repayment_frequency_label)))
LEFT JOIN automn.vw_ref_code AS c_suit
  ON c_suit.submission_type = 'COMMERCIAL'
  AND c_suit.code_list = 'suit_filed_status'
  AND c_suit.code_key = UPPER(NULLIF(LTRIM(RTRIM(n.suit_filed_status)), ''));
